"""Write the parts of docs/ that come from the library itself.

- docs/tools/: one page per tool and an index, from the tool registry.
- docs/expressions.md: the function table, between its two marker lines.
- docs/command.md: each command's --help text, between its two marker lines.
- docs/pipeline-file.md: the keys the loader and the project file accept, between marker lines.
- docs/upgrading.md: the rename table, from src/dantron_etl/renames.py, between marker lines.

Run it after changing a tool, a function or the command:

    python docs/_build/generate.py

tests/package/test_generated_docs.py fails when a page is out of date.
"""

from __future__ import annotations

import contextlib
import io
import os
import re
import sys
from collections.abc import Mapping
from pathlib import Path
from typing import Any

DOCS = Path(__file__).resolve().parents[1]
TOOLS_DIR = DOCS / "tools"
EXPRESSIONS = DOCS / "expressions.md"
COMMAND = DOCS / "command.md"
PIPELINE_FILE = DOCS / "pipeline-file.md"
UPGRADING = DOCS / "upgrading.md"

FUNCTIONS_START = "<!-- functions: generated by docs/_build/generate.py; do not edit by hand -->"
FUNCTIONS_END = "<!-- functions: end -->"
HELP_START = "<!-- help: generated by docs/_build/generate.py; do not edit by hand -->"
HELP_END = "<!-- help: end -->"
KEYS_START = "<!-- keys: generated by docs/_build/generate.py; do not edit by hand -->"
KEYS_END = "<!-- keys: end -->"
PROJECT_START = "<!-- project keys: generated by docs/_build/generate.py; do not edit by hand -->"
PROJECT_END = "<!-- project keys: end -->"
RENAMES_START = "<!-- renames: generated by docs/_build/generate.py; do not edit by hand -->"
RENAMES_END = "<!-- renames: end -->"

# What each key of a pipeline file means. The loader says which keys exist and which are required;
# this says what they are for. A key the loader gains without a line here stops the generator.
KEY_MEANINGS: dict[str, dict[str, str]] = {
    "the file": {
        "name": "The pipeline's title, shown in the viewer.",
        "steps": "The list of steps.",
        "lanes": "Horizontal bands on the drawing. A step names one with `lane`.",
        "containers": "Titled boxes round steps that do one job. A step names one with `container`.",
    },
    "a step": {
        "id": "The step's name. Other steps read its output as `id.port`. No dots.",
        "tool": "The tool this step uses, as `dantron-etl tools` lists it.",
        "config": "The tool's settings. A setting the tool does not have is refused.",
        "inputs": "Which earlier output each of the tool's input ports reads: `port: step.port`.",
        "lane": "The lane the step is drawn in. Must be declared under `lanes`.",
        "stage": "A short word shown in the step's detail. Free text: a misspelling is not caught.",
        "container": "The container the step is drawn in. Must be declared under `containers`.",
        "why": "A plain sentence for the reader, shown beside the step.",
    },
    "a lane": {
        "id": "The lane's name, as steps write it.",
        "title": "The heading drawn on the lane.",
        "order": "Where the lane is drawn, smallest first. A whole number.",
    },
    "a container": {
        "id": "The container's name, as steps write it.",
        "title": "The sentence on the box: what its steps do. It is all a closed box shows, so it may not be blank.",
    },
}

PROJECT_MEANINGS: dict[str, str] = {
    "pipeline_folders": "Folders holding pipeline files. Default `[pipelines]`.",
    "runs_folder": "Where runs are saved for the viewer. Default `output_files/runs`.",
    "pipelines": "Settings for each pipeline, under its name (the file name without `.yaml`).",
    "rules": "Under a pipeline: the values its `${rules.name}` references take.",
    "rules_file": "Under a pipeline: a YAML file of rule values, relative to the project folder.",
    "rules_loader": "Under a pipeline: `module:function` in your project that returns the rule values.",
    "focus": "Under a pipeline: the column, or list of columns, the viewer lets you follow.",
}

# The order commands appear in on the command page: the order a newcomer meets them.
COMMANDS = ("new", "view", "run", "check", "tools", "help", "functions", "catalog", "migrate")
HELP_WIDTH = "100"

GENERATED_NOTE = "<!-- Generated by docs/_build/generate.py from the tool registry. Do not edit by hand. -->"


def _shown(value: Any) -> str:
    """A value as a reader would write it in YAML."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if value == "":
        return '""'
    return str(value)


def _cell(text: str) -> str:
    """Text safe inside a Markdown table cell."""
    return " ".join(str(text).split()).replace("|", "\\|")


def _table(header: list[str], rows: list[list[str]]) -> list[str]:
    lines = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    lines += ["| " + " | ".join(_cell(cell) for cell in row) + " |" for row in rows]
    return lines


def _setting_rows(name: str, field: Mapping[str, Any]) -> list[list[str]]:
    """One row per setting, then the settings nested inside it."""
    if field.get("required"):
        need = "required"
    elif "default" in field:
        need = f"default `{_shown(field['default'])}`"
    else:
        need = "optional"
    allowed = ", ".join(f"`{_shown(value)}`" for value in field.get("allowed", ()))
    rows = [[f"`{name}`", field.get("type", ""), need, allowed, field.get("description", "")]]
    items = field.get("items")
    if items and items.get("fields"):
        for inner, inner_field in items["fields"].items():
            rows += _setting_rows(f"{name}[].{inner}", inner_field)
    elif items:
        rows += _setting_rows(f"{name}[]", items)
    for inner, inner_field in field.get("fields", {}).items():
        rows += _setting_rows(f"{name}.{inner}", inner_field)
    return rows


def _frame(port: str, frame: Mapping[str, Any]) -> list[str]:
    columns = list(frame["schema"])
    if not columns:
        return [f"`{port}`: no columns", ""]
    rows = [[_shown(row[column]) for column in columns] for row in frame["rows"]]
    lines = [f"`{port}`" + ("" if rows else " (no rows)"), "", *_table([f"{c}" for c in columns], rows), ""]
    return lines


def tool_page(tool: Mapping[str, Any]) -> str:
    from dantron_etl.catalog import example_yaml

    name = tool["name"]
    out = [GENERATED_NOTE, "", f"# `{name}`", "", f"*{tool['category']} tool.* {tool['description']}", ""]
    if tool["detail"]:
        out += [tool["detail"], ""]
    reads = ", ".join(f"`{port}`" for port in tool["input_ports"]) or "nothing"
    gives = ", ".join(f"`{port}`" for port in tool["output_ports"]) or "nothing"
    out += ["## Ports", "", f"- **Reads:** {reads}"]
    if tool["ports_from_config"]:
        out += ["  (a step reads the ports its own settings name; these are the example's)"]
    out += [f"- **Gives:** {gives}", "", "## Settings", ""]
    if tool["config"]:
        rows = [row for key, field in tool["config"].items() for row in _setting_rows(key, field)]
        out += _table(["setting", "type", "required or default", "allowed values", "what it is"], rows)
        out.append("")
        if tool["field_help"]:
            out += ["More on some settings:", ""]
            out += [f"- `{key}`: {' '.join(text.split())}" for key, text in tool["field_help"].items()]
            out.append("")
    else:
        out += ["None.", ""]
    if tool["notes"]:
        out += ["## Notes", ""]
        out += [f"- {' '.join(note.split())}" for note in tool["notes"]]
        out.append("")
    for number, example in enumerate(tool["examples"], start=1):
        out += [f"## Example {number}", "", " ".join(example["scenario"].split()), ""]
        out += ["```yaml fragment", f"tool: {name}", "config:"]
        out += ["  " + line for line in example_yaml(example["configuration"]).splitlines()]
        out += ["```", "", "Rows in:", ""]
        for port, frame in example["inputs"].items():
            out += _frame(port, frame)
        out += ["Rows out:", ""]
        for port, frame in example["outputs"].items():
            out += _frame(port, frame)
        if example["explanation"]:
            out += [" ".join(example["explanation"].split()), ""]
    out += ["---", "", "[All tools](README.md)"]
    return "\n".join(out).rstrip() + "\n"


def tools_index(tools: list[Mapping[str, Any]]) -> str:
    from dantron_etl.catalog import CATEGORY_ORDER

    out = [
        GENERATED_NOTE,
        "",
        "# The tools",
        "",
        f"{len(tools)} tools, grouped by what they do. Each page lists the tool's ports and settings, "
        "the rules it follows, and worked examples. Every worked example is run by the test suite, "
        "so the rows shown are what the tool really gives.",
        "",
        "The same text is in the terminal: `dantron-etl tools` and `dantron-etl help <tool>`.",
        "",
    ]
    by_category: dict[str, list[Mapping[str, Any]]] = {}
    for tool in sorted(tools, key=lambda tool: tool["name"]):
        by_category.setdefault(tool["category"], []).append(tool)
    order = [c for c in CATEGORY_ORDER if c in by_category] + sorted(set(by_category) - set(CATEGORY_ORDER))
    for category in order:
        out += [f"## {category}", ""]
        out += _table(
            ["tool", "what it does"],
            [[f"[`{t['name']}`]({t['name']}.md)", t["description"]] for t in by_category[category]],
        )
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def _argument(parameter: Any) -> str:
    """What one function argument must be, in a few words."""
    kind = type(parameter).__name__
    if kind == "Value":
        family = parameter.family.value if parameter.family is not None else "any value"
        return f"a whole number ({family})" if parameter.whole else family
    if kind == "WholeNumber":
        return "a whole number written in the file"
    if kind == "Choice":
        return " or ".join(f"'{option}'" for option in parameter.options)
    if kind == "Pattern":
        return "a quoted pattern"
    if kind == "QuotedText":
        return "quoted text written in the file"
    if kind == "Namespace":
        return "a quoted UUID"
    return kind


def functions_table() -> str:
    from dantron_etl.expr.functions import DEFINITIONS

    rows = []
    for definition in DEFINITIONS:
        arguments = [_argument(parameter) for parameter in definition.params]
        if definition.variadic:
            arguments = [f"two or more, each {arguments[0]}"]
        rows.append([f"`{definition.name}`", "; ".join(arguments), definition.summary, f"`{definition.example}`"])
    lines = [
        f"{len(DEFINITIONS)} functions. `dantron-etl functions` prints the same list.",
        "",
        *_table(["function", "arguments, in order", "what it gives", "example"], rows),
    ]
    return "\n".join(lines)


def command_help() -> str:
    from dantron_etl.cli import main

    # argparse wraps to the terminal's width; a fixed width keeps the page the same on every machine.
    before = os.environ.get("COLUMNS")
    os.environ["COLUMNS"] = HELP_WIDTH
    blocks = []
    try:
        for name, arguments in [("dantron-etl", ["--help"])] + [(f"dantron-etl {c}", [c, "--help"]) for c in COMMANDS]:
            printed = io.StringIO()
            with contextlib.redirect_stdout(printed), contextlib.suppress(SystemExit):
                main(arguments)
            text = printed.getvalue().rstrip()
            blocks.append(f"### `{name}`\n\n```text\n{text}\n```")
    finally:
        if before is None:
            del os.environ["COLUMNS"]
        else:
            os.environ["COLUMNS"] = before
    return "\n\n".join(blocks)


def pipeline_keys() -> str:
    from dantron_etl import loader

    parts = {
        "the file": (loader._DOCUMENT_KEYS, loader._DOCUMENT_REQUIRED, "Top level of the file"),
        "a step": (loader._STEP_KEYS, loader._STEP_REQUIRED, "Each entry under `steps`"),
        "a lane": (loader._LANE_KEYS, loader._LANE_REQUIRED, "Each entry under `lanes`"),
        "a container": (loader._CONTAINER_KEYS, loader._CONTAINER_REQUIRED, "Each entry under `containers`"),
    }
    out: list[str] = []
    for part, (keys, required, heading) in parts.items():
        meanings = KEY_MEANINGS[part]
        missing = [key for key in keys if key not in meanings]
        if missing:
            raise SystemExit(f"docs/_build/generate.py: say what {part}'s key(s) {missing} mean in KEY_MEANINGS")
        rows = [[f"`{key}`", "required" if key in required else "optional", meanings[key]] for key in keys]
        out += [f"**{heading}**", "", *_table(["key", "", "what it is"], rows), ""]
    return "\n".join(out).rstrip()


def project_keys() -> str:
    from dantron_etl.viewer import project

    keys = [*project._TOP_KEYS, *project._ENTRY_KEYS]
    missing = [key for key in keys if key not in PROJECT_MEANINGS]
    if missing:
        raise SystemExit(f"docs/_build/generate.py: say what project key(s) {missing} mean in PROJECT_MEANINGS")
    return "\n".join(_table(["key", "what it is"], [[f"`{key}`", PROJECT_MEANINGS[key]] for key in keys]))


def renames_table() -> str:
    from dantron_etl import renames as r

    rows: list[list[str]] = []
    rows += [["tool", f"`{old}`", f"`{new}`"] for old, new in r.TOOL_RENAMES.items()]
    for tool, fields in r.FIELD_RENAMES.items():
        rows += [[f"`{tool}` setting", f"`{old}`", f"`{new}`"] for old, new in fields.items()]
    for (tool, field), values in r.VALUE_RENAMES.items():
        rows += [[f"`{tool}` `{field}` value", f"`{old}`", f"`{new}`"] for old, new in values.items()]
    for tool, ports in r.OUTPUT_PORT_RENAMES.items():
        rows += [[f"`{tool}` output port", f"`{old}`", f"`{new}`"] for old, new in ports.items()]
    for tool, ports in r.INPUT_PORT_RENAMES.items():
        rows += [[f"`{tool}` input port", f"`{old}`", f"`{new}`"] for old, new in ports.items()]
    rows += [["top-level key", f"`{old}`", f"`{new}`"] for old, new in r.DOCUMENT_KEY_RENAMES.items()]
    rows += [["step key", f"`{old}`", f"`{new}`"] for old, new in r.STEP_KEY_RENAMES.items()]
    rows += [["lane key", f"`{old}`", f"`{new}`"] for old, new in r.LANE_KEY_RENAMES.items()]
    rows += [["expression function", f"`{old}()`", f"`{new}()`"] for old, new in r.FUNCTION_RENAMES.items()]
    out = _table(["what", "old name", "new name"], rows)
    if r.RENAME_NOTES:
        out += ["", "A renamed value whose meaning changed with it:", ""]
        out += [f"- `{old}` to `{new}`: {note}." for (old, new), note in r.RENAME_NOTES.items()]
    if r.OLD_DEFAULTS:
        out += ["", "A default that changed. The migration writes the old value into a step that relied on it:", ""]
        for tool, fields in r.OLD_DEFAULTS.items():
            out += [f"- `{tool}`: " + ", ".join(f"`{field}: {value}`" for field, value in fields.items())]
    out += ["", "Settings a step must now state. The migration writes the value that keeps the old behaviour:", ""]
    for tool, where, when, setting, value in r.STATED_NOW:
        place = f" in each `{where}` entry" if where else ""
        condition = " where " + ", ".join(f"`{k}: {v}`" for k, v in when.items()) if when else ""
        out += [f"- `{tool}`{place}{condition}: `{setting}: {_shown(value)}`"]
    out += ["", "Python names (the migration prints these; change them by hand):", ""]
    out += _table(
        ["old", "new"],
        [
            [f"`{old}`" if " " not in old else old, f"`{new}`" if " " not in new else new]
            for old, new in r.PYTHON_RENAMES
        ],
    )
    return "\n".join(out)


def _between(text: str, start: str, end: str, inner: str, page: Path) -> str:
    pattern = re.compile(re.escape(start) + r".*?" + re.escape(end), re.DOTALL)
    if not pattern.search(text):
        raise SystemExit(f"{page} has no marker lines {start!r} ... {end!r}")
    return pattern.sub(lambda _: f"{start}\n\n{inner}\n\n{end}", text, count=1)


def render() -> dict[Path, str]:
    """Every generated page, keyed by its path, as it should be on disk."""
    from dantron_etl.catalog import catalog

    tools = catalog()["tools"]
    pages: dict[Path, str] = {TOOLS_DIR / "README.md": tools_index(tools)}
    pages.update({TOOLS_DIR / f"{tool['name']}.md": tool_page(tool) for tool in tools})
    pages[EXPRESSIONS] = _between(
        EXPRESSIONS.read_text(encoding="utf8"), FUNCTIONS_START, FUNCTIONS_END, functions_table(), EXPRESSIONS
    )
    pages[COMMAND] = _between(COMMAND.read_text(encoding="utf8"), HELP_START, HELP_END, command_help(), COMMAND)
    text = _between(PIPELINE_FILE.read_text(encoding="utf8"), KEYS_START, KEYS_END, pipeline_keys(), PIPELINE_FILE)
    pages[PIPELINE_FILE] = _between(text, PROJECT_START, PROJECT_END, project_keys(), PIPELINE_FILE)
    pages[UPGRADING] = _between(
        UPGRADING.read_text(encoding="utf8"), RENAMES_START, RENAMES_END, renames_table(), UPGRADING
    )
    return pages


def stale_tool_pages() -> list[Path]:
    """Pages in docs/tools/ for a tool that no longer exists."""
    expected = set(render())
    return sorted(path for path in TOOLS_DIR.glob("*.md") if path not in expected)


def main() -> int:
    pages = render()
    TOOLS_DIR.mkdir(exist_ok=True)
    changed = 0
    for path, text in pages.items():
        if not path.exists() or path.read_text(encoding="utf8") != text:
            path.write_text(text, encoding="utf8", newline="\n")
            changed += 1
            print(f"wrote {path.relative_to(DOCS.parent)}")
    for path in stale_tool_pages():
        path.unlink()
        print(f"removed {path.relative_to(DOCS.parent)}")
    print(f"{changed} page(s) changed, {len(pages)} checked.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
